import timefrom Sengo1 import *from mpython import *from machine import UARTuart1 = UART(1, baudrate=115200, tx=Pin.P14, rx=Pin.P13)sengo1 = Sengo1(0x60)# 自定义函数def UART():  global my_variable, key_N, key_P, key_T, key_H, key_A, key_B, start, angle  sengo1.begin(uart1)def I2C():  global my_variable, key_N, key_P, key_T, key_H, key_A, key_B, start, angle  sengo1.begin(i2c)def Forward():  global my_variable, key_N, key_P, key_T, key_H, key_A, key_B, start, angle  oled.DispChar("Straight", 0, (3-1)*16, 1)def Display():  global my_variable, key_N, key_P, key_T, key_H, key_A, key_B, start, angle  oled.fill_rect(0, (2-1)*16, 128, 16, 0)  oled.fill_rect(0, (3-1)*16, 128, 16, 0)  oled.show()  # Sengo1不主动返回检测识别结果，需要主控板发送指令进行读取。读取的流程：首先读取识别结果的数量，接收到指令后，Sengo1会刷新结果数据，如果结果数量不为零，那么主控再发送指令读取结果的相关信息。请务必按此流程构建程序。  # Sengo最多输出1个识别结果。  if ((sengo1.GetValue(sengo1_vision_e.kVisionLine, sentry_obj_info_e.kStatus)) > 0):    angle = (sengo1.GetValue(sengo1_vision_e.kVisionLine,sentry_obj_info_e.kLabel))    oled.DispChar((str(angle)), 0, (2-1)*16, 1)    if (angle < 45):      Hard_Right()    if ((45 < angle) and (angle < 80)):      Right()    if ((80 < angle) and (angle < 100)):      Forward()    if ((100 < angle) and (angle < 135)):      Left()    if (135 < angle):      Hard_Left()  else:    Stop()  oled.show()  time.sleep(0.1)def Left():  global my_variable, key_N, key_P, key_T, key_H, key_A, key_B, start, angle  oled.DispChar("Left", 0, (3-1)*16, 1)def Hard_Left():  global my_variable, key_N, key_P, key_T, key_H, key_A, key_B, start, angle  oled.DispChar("Hard Left", 0, (3-1)*16, 1)def Right():  global my_variable, key_N, key_P, key_T, key_H, key_A, key_B, start, angle  oled.DispChar("Right", 0, (3-1)*16, 1)def Hard_Right():  global my_variable, key_N, key_P, key_T, key_H, key_A, key_B, start, angle  oled.DispChar("Hard Right", 0, (3-1)*16, 1)def Stop():  global my_variable, key_N, key_P, key_T, key_H, key_A, key_B, start, angle  oled.DispChar("Stop", 0, (3-1)*16, 1)# 事件回调函数def on_button_a_down(_):  time.sleep_ms(10)  if button_a.value() == 1: return  global start  start = 1def on_button_b_down(_):  time.sleep_ms(10)  if button_b.value() == 1: return  global start  start = 0button_a.irq(trigger=Pin.IRQ_FALLING, handler=on_button_a_down)button_b.irq(trigger=Pin.IRQ_FALLING, handler=on_button_b_down)angle = 0start = 0# 等待Sengo1完成初始化，此延时不可以去掉，避免Sengo1初始化尚未完成，主控板已经发送指令time.sleep(2)oled.DispChar("Algo: Line", 0, 0, 1)oled.show()I2C()# 1、参考文档（注：Sengo1与Sentry1是两款产品）# https://tosee.readthedocs.io/zh/latest/Sentry1/Vision/index.html#chapter-vs1-vision-line-index# 2、算法的常见应用：巡线；# 3、使用时请注意：线条应与背景有明显差异，常见为白纸黑线；线条的宽度适中，譬如1.5cm；地图的表面不应光滑，避免发生反光问题；# 4、Sengo1每次只能运行一种识别算法；# 5、正常使用时，应由主控板通过指令控制Sengo1算法的开启与关闭，而不是通过Sengo1的按键进行操作；sengo1.VisionBegin(sengo1_vision_e.kVisionLine)while True:  if (start == 1):    Display()